import{c as a,S as s,j as n,m as r}from"./chunks/framework.DvQr6YbT.js";const b=JSON.parse('{"title":"项目介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),e={name:"guide/introduction.md"};function d(i,t,o,l,p,c){return s(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to “项目介绍”">​</a></h1><p>WZ Spring Boot Starter 是一套面向企业级 Java 项目的 <strong>Spring Boot Starter 套件</strong>，目标是让用户在任何新项目中快速启动，并将通用横切能力封装为可复用模块。</p><h2 id="解决的问题" tabindex="-1">解决的问题 <a class="header-anchor" href="#解决的问题" aria-label="Permalink to “解决的问题”">​</a></h2><p>新建 Spring Boot 项目时，团队通常需要重复搭建以下基础设施：</p><ul><li>统一 API 响应格式</li><li>全局异常处理</li><li>参数校验与错误码规范</li><li>数据库分页、审计字段</li><li>Redis 缓存与分布式锁</li><li>JWT 认证与权限控制</li><li>链路追踪与操作日志</li><li>文件存储、消息队列、定时任务</li></ul><p>WZ Starter 将这些能力封装为独立模块，通过 <strong>引入依赖 + 少量配置</strong> 即可启用。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to “技术栈”">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>版本</th></tr></thead><tbody><tr><td>Java</td><td>17+</td></tr><tr><td>Spring Boot</td><td>3.4.5</td></tr><tr><td>MyBatis-Plus</td><td>3.5.9</td></tr><tr><td>Redisson</td><td>3.41.0</td></tr><tr><td>Hutool</td><td>5.8.35</td></tr><tr><td>MapStruct</td><td>1.6.3</td></tr></tbody></table><h2 id="设计理念" tabindex="-1">设计理念 <a class="header-anchor" href="#设计理念" aria-label="Permalink to “设计理念”">​</a></h2><table tabindex="0"><thead><tr><th>原则</th><th>说明</th></tr></thead><tbody><tr><td>约定优于配置</td><td>零配置即可运行，80% 场景开箱即用</td></tr><tr><td>按需装配</td><td>模块化 Starter，用户只引入需要的模块</td></tr><tr><td>分层解耦</td><td>common（纯 Java）→ core（Spring 基础）→ 能力 Starter</td></tr><tr><td>可扩展</td><td>SPI + <code>@ConditionalOnMissingBean</code>，业务可覆盖默认实现</td></tr><tr><td>快速创建</td><td>BOM 统一版本 + Maven Archetype 一键脚手架</td></tr></tbody></table><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to “项目结构”">​</a></h2><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wz-spring-boot-starter/</span></span>
<span class="line"><span>├── wz-dependencies/              # BOM，统一依赖版本</span></span>
<span class="line"><span>├── wz-common/                    # 无 Spring 依赖：Result、异常、工具类</span></span>
<span class="line"><span>├── wz-spring-boot-starter-core/  # 核心自动配置、全局 wz.* 属性</span></span>
<span class="line"><span>├── wz-spring-boot-starter-web/   # 全局异常、CORS、参数校验</span></span>
<span class="line"><span>├── wz-spring-boot-starter-mybatis/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-redis/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-security/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-log/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-oss/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-mq/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-job/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-monitor/</span></span>
<span class="line"><span>├── wz-spring-boot-starter-test/</span></span>
<span class="line"><span>└── docs/                         # VitePress 文档站点</span></span></code></pre></div><h2 id="实施进度" tabindex="-1">实施进度 <a class="header-anchor" href="#实施进度" aria-label="Permalink to “实施进度”">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>状态</th></tr></thead><tbody><tr><td>P0</td><td>common + core + web</td><td>✅ 已完成</td></tr><tr><td>P1</td><td>mybatis + redis + log</td><td>🚧 规划中</td></tr><tr><td>P2</td><td>security + monitor</td><td>🚧 规划中</td></tr><tr><td>P3</td><td>oss + mq + job</td><td>🚧 规划中</td></tr><tr><td>P4</td><td>test + archetype 脚手架</td><td>🚧 规划中</td></tr></tbody></table>`,14)])])}const g=a(e,[["render",d]]);export{b as __pageData,g as default};
